(() => {
  const STORAGE_KEY='garden-labs-machines-v1'; let catalog=null,instances=[]; const $=s=>document.querySelector(s); const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function setMachineView(on){const ms=$('#machinesSurface'),gs=$('#guideSurface'),ss=$('#seedsSurface'),mt=$('#machinesTab'),gt=$('#guideTab'),st=$('#seedsTab');if(!ms)return;ms.hidden=!on;if(on){gs.hidden=true;ss.hidden=true;mt.classList.add('active');mt.setAttribute('aria-pressed','true');[gt,st].forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});localStorage.setItem('gardenLabsLibraryView','machines');$('#productEyebrow').textContent='GARDEN LABS · MACHINES';$('#productTitle').textContent='Machines';render()}else{mt.classList.remove('active');mt.setAttribute('aria-pressed','false')}}
  function bindNav(){ $('#machinesTab')?.addEventListener('click',()=>setMachineView(true)); ['#guideTab','#seedsTab'].forEach(s=>$(s)?.addEventListener('click',()=>setMachineView(false))); if(localStorage.getItem('gardenLabsLibraryView')==='machines')setMachineView(true); }
  async function load(){catalog=await fetch('./data/machine-inventory-v1.json').then(r=>r.json());const saved=localStorage.getItem(STORAGE_KEY);instances=saved?JSON.parse(saved):structuredClone(catalog.instances);bindNav();render()}
  function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(instances));render()} function model(i){return catalog.models.find(m=>m.id===i.modelId)} function stars(v){return v?`★ ${Number(v).toFixed(1)}`:'Sin calificar'}
  function render(){const grid=$('#machineGrid');if(!grid||!catalog)return;$('#machineResultCount').textContent=`${instances.length} máquinas · ${catalog.models.reduce((a,m)=>a+m.pods,0)} posiciones`;grid.innerHTML=instances.map(i=>{const m=model(i);return `<article class="machine-card"><button class="machine-card-button" data-machine="${i.id}"><div class="machine-photo machine-${m.color}"><span>${m.brand}</span><strong>${m.pods}</strong><small>PODS</small></div><div><p class="machine-brand">${esc(m.brand)}</p><h4>${esc(m.name)}</h4><p class="muted">${esc(m.model)}</p></div><div class="machine-card-meta"><span>${m.pods} pods</span><span class="machine-status ${i.status}">${i.status}</span><span>${stars(i.overallRating)}</span></div></button></article>`}).join('');grid.querySelectorAll('[data-machine]').forEach(b=>b.onclick=()=>open(b.dataset.machine))}
  function open(id){const i=instances.find(x=>x.id===id),m=model(i),d=$('#machineDetail');d.innerHTML=`<div class="machine-detail-head"><div class="machine-photo machine-${m.color}"><span>${m.brand}</span><strong>${m.pods}</strong><small>PODS</small></div><div><p class="eyebrow">MY MACHINE</p><h2>${esc(m.name)}</h2><p>${esc(m.model)} · ${m.pods} pods</p></div></div><form id="machineForm"><h3>Mi unidad</h3><div class="machine-form-grid"><label>Estado<select name="status">${catalog.allowedStatuses.map(x=>`<option ${i.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Fecha de compra<input type="date" name="purchaseDate" value="${i.purchase.date||''}"></label><label>Lugar / vendedor<input name="seller" value="${esc(i.purchase.seller||'')}"></label><label>Canal<select name="channel"><option value=""></option>${catalog.purchaseChannels.map(x=>`<option value="${x}" ${i.purchase.channel===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Precio pagado (USD)<input type="number" step="0.01" min="0" name="price" value="${i.purchase.priceUsd??''}"></label><label>Fecha recibida<input type="date" name="receivedDate" value="${i.receivedDate||''}"></label><label>Primer uso<input type="date" name="firstUseDate" value="${i.firstUseDate||''}"></label><label>Ubicación<input name="location" value="${esc(i.location||'')}"></label></div><h3>Mi evaluación</h3><div class="rating-grid">${catalog.ratingDimensions.map(r=>`<label>${r.es}<select name="rating-${r.id}"><option value="">—</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${i.ratings[r.id]==n?'selected':''}>${'★'.repeat(n)} (${n})</option>`).join('')}</select></label>`).join('')}</div><div class="machine-form-grid"><label>Overall Rating<select name="overall"><option value="">—</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${i.overallRating==n?'selected':''}>${'★'.repeat(n)} (${n})</option>`).join('')}</select></label><label>¿La comprarías otra vez?<select name="buyAgain"><option value="">—</option>${catalog.wouldBuyAgainValues.map(x=>`<option ${i.wouldBuyAgain===x?'selected':''}>${x}</option>`).join('')}</select></label></div><label>Notas<textarea name="notes" rows="3">${esc(i.notes)}</textarea></label><h3>Model Specs</h3><div class="machine-specs"><span><b>Tanque</b> ${typeof m.tankLiters==='object'?`${m.tankLiters.min}–${m.tankLiters.max}`:m.tankLiters} L</span><span><b>Color</b> ${m.color}</span><span><b>Pods</b> ${m.pods}</span><span><b>Luz</b> ${m.light.watts?m.light.watts+'W · ':''}${m.light.modes?m.light.modes.join(' / '):'Timer automático'}</span></div><div class="machine-form-actions"><button type="submit" class="lab-primary-button">Guardar cambios</button></div></form>`;$('#machineForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);i.status=f.get('status');i.purchase={date:f.get('purchaseDate')||null,seller:f.get('seller')||null,channel:f.get('channel')||null,priceUsd:f.get('price')?Number(f.get('price')):null};i.receivedDate=f.get('receivedDate')||null;i.firstUseDate=f.get('firstUseDate')||null;i.location=f.get('location')||null;i.notes=f.get('notes')||'';catalog.ratingDimensions.forEach(r=>{const v=f.get(`rating-${r.id}`);if(v)i.ratings[r.id]=Number(v);else delete i.ratings[r.id]});i.overallRating=f.get('overall')?Number(f.get('overall')):null;i.wouldBuyAgain=f.get('buyAgain')||null;save();$('#machineDialog').close()};$('#machineDialog').showModal()}
  window.GardenMachinesV1={load,render};document.addEventListener('DOMContentLoaded',load)
})();